using SinePlayer.Core.Playback.Abstractions;
using SinePlayer.Core.Playback.Abstractions.Decode;
using SinePlayer.Core.Playback.Abstractions.Info;
using SinePlayer.Core.Playback.Abstractions.Source;
using SinePlayer.Core.Playback.Backends.FFmpeg;

namespace SinePlayer.Core.Tests.Playback;

/// <summary>
/// Decodes a real, temporally compressed stream, generated by <see cref="Av1FixtureFile"/>, so the video
/// path is exercised against a stream that has a sequence header, reference frames and a container â€”
/// unlike the single frame bitmap the other decoder tests use.
/// </summary>
[TestFixture]
public class AV1FixtureTests
{
    [Test]
    public void DecodesAGeneratedAv1Stream()
    {
        string path = Av1FixtureFile.Create();
        try
        {
            DecodeFile(path);
        }
        finally
        {
            File.Delete(path);
        }
    }

    private static void DecodeFile(string path)
    {
        TestContext.Progress.WriteLine($"fixture: {path} ({new FileInfo(path).Length} bytes)");

        FFmpegSourceProviderFactory sourceFactory = new();
        PlaybackOperationResult openResult = sourceFactory.TryOpen(MediaLocator.Parse(path), out IMediaSource? source);
        Assert.That(openResult.IsSuccessful, Is.True, openResult.Message);

        using IMediaSource mediaSource = source!;
        Assert.That(mediaSource.Info.VideoStreams, Is.Not.Empty);
        VideoStreamInfo stream = mediaSource.Info.VideoStreams[0];
        Assert.That(stream.CodecId, Is.EqualTo("av1"));
        Assert.That(stream.Width, Is.EqualTo(Av1FixtureFile.Width));
        Assert.That(stream.Height, Is.EqualTo(Av1FixtureFile.Height));

        FFmpegVideoDecoderFactory decoderFactory = new();
        PlaybackOperationResult decoderResult = decoderFactory.TryCreate(mediaSource, stream, DecoderOptions.Default, out IVideoDecoder? decoder);
        Assert.That(decoderResult.IsSuccessful, Is.True, decoderResult.Message);

        using IVideoDecoder videoDecoder = decoder!;
        int decoded = 0;
        TimeSpan lastTimestamp = TimeSpan.Zero;
        while (true)
        {
            PlaybackOperationResult readResult = mediaSource.TryReadPacket(out MediaPacket? packet);
            Assert.That(readResult.IsSuccessful, Is.True, readResult.Message);
            if (packet is null)
            {
                break;
            }

            using (packet)
            {
                if (packet.StreamIndex != stream.Index)
                {
                    continue;
                }

                PlaybackOperationResult decodeResult = videoDecoder.TryDecode(packet, out IReadOnlyList<RawVideoFrame> frames);
                Assert.That(decodeResult.IsSuccessful, Is.True, decodeResult.Message);

                foreach (RawVideoFrame frame in frames)
                {
                    using (Assert.EnterMultipleScope())
                    {
                        Assert.That(frame.Width, Is.EqualTo(Av1FixtureFile.Width));
                        Assert.That(frame.Height, Is.EqualTo(Av1FixtureFile.Height));
                        Assert.That(frame.Buffer, Is.InstanceOf<IPlanarVideoBuffer>());
                    }

                    if (frame.Timestamp > lastTimestamp)
                    {
                        lastTimestamp = frame.Timestamp;
                    }

                    frame.Dispose();
                    decoded++;
                }
            }
        }

        PlaybackOperationResult drainResult = videoDecoder.Drain(out IReadOnlyList<RawVideoFrame> tail);
        Assert.That(drainResult.IsSuccessful, Is.True, drainResult.Message);
        foreach (RawVideoFrame frame in tail)
        {
            frame.Dispose();
            decoded++;
        }

        // AV1 has a decoder delay, so a drained decoder is expected to be within a frame or two of the
        // number of frames the fixture contains.
        Assert.That(decoded, Is.GreaterThanOrEqualTo(Av1FixtureFile.FrameCount - 2));

        // The fixture is deliberately longer than a second. A conversion that clamped timestamps past a
        // second to zero made every frame after the first second look infinitely late, which the short
        // fixtures could never show.
        Assert.That(lastTimestamp, Is.GreaterThan(TimeSpan.FromSeconds(1)));
    }
}
